BEGIN;
CREATE TABLE IF NOT EXISTS pooling.asset_position(asset_id uuid PRIMARY KEY,asset_code text NOT NULL,currency_code text NOT NULL CHECK(currency_code~'^[A-Z]{3}$'),outstanding_amount numeric(30,12) NOT NULL CHECK(outstanding_amount>=0),updated_at timestamptz NOT NULL DEFAULT clock_timestamp());
CREATE TABLE IF NOT EXISTS pooling.asset_allocation_version(allocation_id uuid PRIMARY KEY,asset_id uuid NOT NULL REFERENCES pooling.asset_position(asset_id),pool_id text NOT NULL REFERENCES pooling.pool(pool_id),percentage numeric(9,6) NOT NULL CHECK(percentage>0 AND percentage<=100),effective_from date NOT NULL,effective_to date,justification text NOT NULL CHECK(length(trim(justification))>=10),approval_id text,created_at timestamptz NOT NULL DEFAULT clock_timestamp(),idempotency_key text NOT NULL UNIQUE,CHECK(effective_to IS NULL OR effective_to>effective_from));
CREATE INDEX IF NOT EXISTS asset_allocation_history_idx ON pooling.asset_allocation_version(asset_id,effective_from,effective_to);
CREATE OR REPLACE FUNCTION pooling.prevent_asset_overallocation()RETURNS trigger LANGUAGE plpgsql AS $$DECLARE allocated numeric;BEGIN PERFORM pg_advisory_xact_lock(hashtextextended(NEW.asset_id::text,0));SELECT COALESCE(sum(percentage),0) INTO allocated FROM pooling.asset_allocation_version WHERE asset_id=NEW.asset_id AND allocation_id<>NEW.allocation_id AND daterange(effective_from,COALESCE(effective_to,'infinity'::date),'[)')&&daterange(NEW.effective_from,COALESCE(NEW.effective_to,'infinity'::date),'[)');IF allocated+NEW.percentage>100 THEN RAISE EXCEPTION 'Asset allocation exceeds 100 percent';END IF;RETURN NEW;END;$$;DROP TRIGGER IF EXISTS asset_allocation_capacity ON pooling.asset_allocation_version;CREATE TRIGGER asset_allocation_capacity BEFORE INSERT OR UPDATE ON pooling.asset_allocation_version FOR EACH ROW EXECUTE FUNCTION pooling.prevent_asset_overallocation();
CREATE OR REPLACE FUNCTION pooling.reject_allocation_delete()RETURNS trigger LANGUAGE plpgsql AS $$BEGIN RAISE EXCEPTION 'Asset allocation history cannot be deleted';END;$$;DROP TRIGGER IF EXISTS asset_allocation_no_delete ON pooling.asset_allocation_version;CREATE TRIGGER asset_allocation_no_delete BEFORE DELETE ON pooling.asset_allocation_version FOR EACH ROW EXECUTE FUNCTION pooling.reject_allocation_delete();
COMMIT;
